-- ============================================================================
-- Cetking Universe — VERBAL MASTER TAXONOMY  (RESHAPE, run #2)
--
-- The table already holds the Critical Reasoning restructure (143 rows, loaded
-- and verified). Ravneet then restructured three more sub-sections, so this ONE
-- file carries all of them:
--
--   READING COMPREHENSION — Evidence and Summary/TSPM stop being sub-sections
--   and become chapters inside RC: Evidence based, TSPM based, CAT level RC.
--   Except Based becomes a tag, not a chapter.
--
--   PARAGRAPH — 4 chapters. Sentence Insertion merges into Para Completion;
--   Mandatory Pair into TITA or with-options; renamed to "Para Completion" and
--   "Para Formation"; the with-options jumble splits 5 vs 6-7 Statements.
--   Passage Structure dropped — no question exists for it in any bank.
--
--   VOCABULARY — rebuilt to his 15 Oct spec:
--       Section > Subsection > Topic > Subtopic > [Dimension] > Question Type
--   3 Topics, 11 Subtopics, 22 Question Types. This needs TWO schema additions,
--   both made below: a new level 'subtopic', and a 'dimension' column (1D / 2D,
--   with room for 3D). Dimension is a COMPLEXITY TAG, not a level — his words.
--
-- Column mapping (the table mirrors quant_master_taxonomy, so the names differ
-- from his words — read this before querying):
--       his Topic         -> level 'chapter'   -> chapter_id / chapter_name
--       his Subtopic      -> level 'subtopic'  -> topic_id / topic_name
--       his Question Type -> level 'core_type' -> core_type_id / core_type_name
--
-- Result: 115 rows (1 section, 6 subsections, 28 topics/chapters,
-- 13 subtopics, 67 question types). Grammar and General are UNTOUCHED —
-- Ravneet is still working on those.
--
-- Safe to re-run. Deletes every row and reloads all 115 in ONE transaction. The
-- 14 Critical Reasoning core-type ids reload unchanged, so the 249 questions
-- already tagged with ck_core_id stay valid — and the file asserts that before
-- it commits.
-- ============================================================================

begin;

-- ─── STEP 1 · Control Room: register session + change request ───────────────
insert into control_room.sessions (actor, agent_type, purpose, status, notes)
values ('claude', 'opus', 'Reshape public.verbal_master_taxonomy: RC + Paragraph + Vocabulary (115 rows)',
        'active', 'Ravneet restructured Reading Comprehension, Paragraph and Vocabulary on 15 Oct 2026. Vocabulary introduces his Topic > Subtopic > Dimension > Question Type shape, so this adds the subtopic level and the dimension column. File of truth: reference-bank/verbal/master-taxonomy.csv in CetkingLearning/questions-universe.');

insert into control_room.change_requests (session_id, title, rationale, affected_objects, proposed_action, status, risk_level, rollback_notes)
select s.id,
  'Verbal master taxonomy: reshape for RC + Paragraph + Vocabulary (143 -> 115 rows)',
  'Rav rule 15 Oct 2026: one master taxonomy per section, an ID at every level. He restructured three sub-sections and specified a Topic > Subtopic > Dimension > Question Type shape for Vocabulary.',
  array['public.verbal_master_taxonomy','public.verbal_master_taxonomy_chapters'],
  'ALTER the level check constraint to allow ''subtopic''; ADD COLUMN dimension; DELETE all taxonomy rows and reload 115. The 14 CR core-type ids reload unchanged so the 249 tagged questions stay valid (asserted). No question row touched.',
  'in_progress', 'low',
  'Re-run the previous file to restore the earlier shape; the CR ids and all question tags are unaffected either way.'
from control_room.sessions s
where s.actor='claude' and s.status='active'
  and s.purpose like 'Reshape public.verbal_master_taxonomy%'
order by s.started_at desc limit 1;

-- ─── STEP 2 · schema additions for his deeper Vocabulary tree ───────────────
-- a) allow the new 'subtopic' level
alter table public.verbal_master_taxonomy drop constraint if exists verbal_master_taxonomy_level_check;
alter table public.verbal_master_taxonomy add  constraint verbal_master_taxonomy_level_check
  check (level in ('section','subsection','chapter','subtopic','core_type'));

-- b) the dimension tag (1D / 2D / 3D later). NOT a level — a complexity layer.
alter table public.verbal_master_taxonomy add column if not exists dimension text;
alter table public.verbal_master_taxonomy drop constraint if exists verbal_master_taxonomy_dimension_check;
alter table public.verbal_master_taxonomy add  constraint verbal_master_taxonomy_dimension_check
  check (dimension in ('1D','2D','3D') or dimension is null);
comment on column public.verbal_master_taxonomy.dimension is
  'Complexity layer inside a subtopic (Rav, 15 Oct 2026): 1D = one thing tested, 2D = two things at once, 3D reserved. A TAG on the question type, not a level of the tree.';

create index if not exists verbal_master_taxonomy_topic_idx     on public.verbal_master_taxonomy(topic_id);
create index if not exists verbal_master_taxonomy_dimension_idx on public.verbal_master_taxonomy(dimension);

-- ─── STEP 3 · replace the rows ──────────────────────────────────────────────
-- Children before parents: the parent_id foreign key is self-referential.
delete from public.verbal_master_taxonomy where level = 'core_type';
delete from public.verbal_master_taxonomy where level = 'subtopic';
delete from public.verbal_master_taxonomy where level = 'chapter';
delete from public.verbal_master_taxonomy where level = 'subsection';
delete from public.verbal_master_taxonomy where level = 'section';


-- section (1)
insert into public.verbal_master_taxonomy (master_id, level, parent_id, name, section_id, subsection_id, subsection_name, chapter_id, chapter_name, chapter_code, cat_export_chapter, topic_id, topic_no, topic_name, core_type_id, core_type_no, core_type_name, bible_core_id_provisional, sort_order, in_bible, in_question_taxonomy, in_universe_nodes, in_arena, cat_questions_in_chapter, match_status, proposed_addition, source_detail, mother_core_type, rc_non, dimension, white_book_chapter, cat_pyq_in_core_type, exams, exams_basis) values
  ('V', 'section', NULL, 'Verbal', 'V', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, true, true, true, true, 747, 'exact', false, 'Verbal section across all sources', NULL, NULL, NULL, NULL, 506, 'CAT · CET · NMAT · CMAT? · SNAP? · XAT?', 'Verbal appears in every MBA entrance paper; the mix of types differs')
on conflict (master_id) do nothing;

