-- ─── chapter roll-up view ───────────────────────────────────────────────────
-- Dropped first: the column list changed (subtopics / one_d / two_d are new) and
-- CREATE OR REPLACE cannot rename or reorder a view's columns.
drop view if exists public.verbal_master_taxonomy_chapters;
create view public.verbal_master_taxonomy_chapters as
select c.master_id                as chapter_id,
       c.subsection_name,
       c.chapter_name,
       c.chapter_code,
       c.mother_core_type,
       c.white_book_chapter,
       c.cat_export_chapter,
       c.cat_questions_in_chapter,
       c.cat_pyq_in_core_type     as cat_pyq_in_chapter,
       c.exams,
       -- count(distinct ...) throughout: joining BOTH subtopics and core types to
       -- the chapter makes a cartesian product, so a plain count multiplies them.
       count(distinct s.master_id)                                                       as subtopics,
       count(distinct t.master_id)                                                       as core_types,
       count(distinct case when t.match_status = 'exact' then t.master_id end)           as core_types_live,
       count(distinct case when t.proposed_addition     then t.master_id end)            as core_types_proposed,
       count(distinct case when t.dimension = '1D'      then t.master_id end)            as one_d,
       count(distinct case when t.dimension = '2D'      then t.master_id end)            as two_d,
       c.status,
       c.sort_order
from public.verbal_master_taxonomy c
left join public.verbal_master_taxonomy s
       on s.level = 'subtopic'  and s.chapter_id = c.master_id
left join public.verbal_master_taxonomy t
       on t.level = 'core_type' and t.chapter_id = c.master_id
where c.level = 'chapter'
group by c.master_id, c.subsection_name, c.chapter_name, c.chapter_code, c.mother_core_type,
         c.white_book_chapter, c.cat_export_chapter, c.cat_questions_in_chapter,
         c.cat_pyq_in_core_type, c.exams, c.status, c.sort_order
order by c.sort_order;

-- ─── STEP 4 · verify, then Control Room handover ────────────────────────────
do $$
declare n integer; c integer;
begin
  select count(*) into n from public.verbal_master_taxonomy;
  select count(*) into c from public.verbal_master_taxonomy where level='core_type';
  if n <> 115 or c <> 67 then
    raise exception 'Verbal master taxonomy load wrong: % rows (expected 115), % core types (expected 67)', n, c;
  end if;

  select count(*) into n from public.verbal_master_taxonomy where level='subtopic';
  if n <> 13 then raise exception 'expected 13 subtopics, got %', n; end if;

  select count(*) into n from public.verbal_master_taxonomy x
    where x.parent_id is not null
      and not exists (select 1 from public.verbal_master_taxonomy p where p.master_id = x.parent_id);
  if n > 0 then raise exception 'Verbal master taxonomy: % orphan rows', n; end if;

  select count(*) into n from public.verbal_master_taxonomy where level='core_type' and core_type_id is null;
  if n > 0 then raise exception '% core types without a core_type_id', n; end if;

  -- every Vocabulary question type must carry a dimension
  select count(*) into n from public.verbal_master_taxonomy
   where level='core_type' and subsection_id='V-VO' and dimension is null;
  if n > 0 then raise exception '% Vocabulary question types have no dimension', n; end if;

  -- THE IMPORTANT ONE: no question may be left pointing at a core type that no
  -- longer exists. 249 CR questions already carry ck_core_id.
  select count(*) into n from (
    select ck_core_id from public.cat_import_questions     where ck_core_id is not null
    union
    select ck_core_id from public.cat_verbal_pyq_questions where ck_core_id is not null
  ) z where not exists (
    select 1 from public.verbal_master_taxonomy t
     where t.master_id = z.ck_core_id and t.level = 'core_type');
  if n > 0 then
    raise exception 'RESHAPE ABORTED: % tagged core ids would be orphaned by this reload', n;
  end if;
end $$;

insert into control_room.change_events (request_id, session_id, actor, event_kind, object_schema, object_name, operation, details)
select cr.id, cr.session_id, 'claude', 'schema_and_data', 'public', 'verbal_master_taxonomy', 'ALTER+RELOAD',
  jsonb_build_object('summary',
  'Reshaped to 115 rows for Ravneet''s RC, Paragraph and Vocabulary restructures. Added the subtopic level and the dimension column (1D/2D/3D) — dimension is a complexity tag, not a level. Vocabulary is now 3 Topics, 13 Subtopics, 22 Question Types. Verified counts, subtopic count, parent integrity, core_type_id, Vocabulary dimensions, and that every already-tagged ck_core_id still resolves. OUTSTANDING: (1) Idioms and Phrases is NOT in Rav''s Vocabulary spec but has 54 live questions, so it was added as an 11th subtopic under Context and Usage and flagged for his decision; (2) High Frequency Words dropped — zero questions, same rule he applied to Passage Structure; (3) Grammar and General still to come from him; (4) the 246 live Vocabulary questions are not yet tagged with ck_core_id — that is the next step once he confirms Idioms; (5) the cat_card_questions qkey bug must be fixed before any tagging reaches the cards (reference-bank/verbal/CARD-KEY-BUG.md).')
from control_room.change_requests cr
where cr.title = 'Verbal master taxonomy: reshape for RC + Paragraph + Vocabulary (143 -> 115 rows)'
order by cr.created_at desc limit 1;

update control_room.change_requests
   set status='completed', completed_at=now(),
       verification_notes='115 rows, 67 question types, 13 subtopics, no orphans, every Vocabulary type has a dimension, and all 249 existing question tags still resolve — all asserted inside the transaction.'
 where title = 'Verbal master taxonomy: reshape for RC + Paragraph + Vocabulary (143 -> 115 rows)';

update control_room.sessions
   set status='completed', finished_at=now(), last_seen_at=now(),
       notes = coalesce(notes,'') || ' | Done: reshaped to 115 rows.'
 where id = (select id from control_room.sessions
              where actor='claude' and status='active'
                and purpose like 'Reshape public.verbal_master_taxonomy%'
              order by started_at desc limit 1);

commit;
